import re

def parsea_duracion(s):
    if not isinstance(s, str) or not s:
        raise ValueError("Cadena vacía o no válida")

    # Patrón para capturar números seguidos de h, m, o s
    pattern = r'(\d+)([hms])'
    matches = re.findall(pattern, s)

    # Verificar que la cadena completa coincida con el patrón (sin caracteres extra)
    reconstructed = ''.join(f'{num}{unit}' for num, unit in matches)
    if reconstructed != s:
        raise ValueError(f"Cadena no válida: {s}")

    if not matches:
        raise ValueError(f"Cadena no válida: {s}")

    total_seconds = 0
    for num, unit in matches:
        value = int(num)
        if unit == 'h':
            total_seconds += value * 3600
        elif unit == 'm':
            total_seconds += value * 60
        elif unit == 's':
            total_seconds += value

    return total_seconds
```

